import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.TakeItemActor{ItemEntityRuntimeID: 300, TakerEntityRuntimeID: 7}
GOLDEN = bytes.fromhex("ac0207")

# generated by gophertunnel b8bd735:
# packet.TakeItemActor{ItemEntityRuntimeID: 4294967296, TakerEntityRuntimeID: 1}
WIDE = bytes.fromhex("808080801001")

GOLDENS = [
    pytest.param(v2225.TakeItemActorPacket(item_id=300, actor_id=7), GOLDEN, id="narrow"),
    pytest.param(v2225.TakeItemActorPacket(item_id=4294967296, actor_id=1), WIDE, id="wide-item-id"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_take_item_actor_is_packet_17(version):
    assert version.packets[17] is version.TakeItemActorPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_take_item_actor_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_take_item_actor_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
